INSERT INTO "adversarial_findings" ("finding_id", "pass_id", "lens", "subject_table", "subject_key", "claim_attacked", "method", "artefact", "verdict", "severity", "disposition", "disposition_ref", "disposed_by_session", "disposed_at", "created_by_session", "created_at") VALUES (147, 8, 'L7-recognition', 'source_value_extractions', '169', 'lens ALL on AD M Table 2 door widths (169-176) and MOB on ADA 404.2.3 (185); MOB on AD M door force (177-178) and ALL on ADA 404.2.9 (184) are faithful readings of the sources', 'read the surrounding paragraphs in both payloads: AD M 2.11 names wheelchair users for Table 2 (filed ALL) while ADA 404.2.3 names no one (filed MOB); AD M 2.9 names wheelchair users and people with limited strength (filed MOB only) while ADA 404.2.9 names no one (filed ALL); the lens is inverted against the texts and inconsistent across sources for the same parameter', 'retrieval-log/session_2026-10-30-rest-landing-parameter/0e5d4dee25b341f4-full-text.txt', 'SUSTAINED', 'MEDIUM', 'PROVISIONAL-DISPUTED', 'Sustained as to the inconsistency (ADA 304.3.1, 403.5.1 and 404.2.3 filed MOB though their clauses name no population, against ALL on 404.2.9; AD M 2.9 names wheelchair users and limited strength and is filed MOB alone). Not repairable in place: amend-extraction cannot change a lens column and a second row would duplicate the figure. The lens on rows 168-186 is provisional and is the reader''s filing; the crossing is judgment''s output (CLAUDE.md section 6), which re-keys it. The six rows added after the pass use ALL for a clause naming no one.', 'session_2026-11-06-pipeline-batch', '2026-11-06 03:08', 'session_2026-11-06-pipeline-batch', '2026-11-06 03:08');
